// ─────────────────────────────────────────────────────────
// BIG-O ANIMATION CANVAS
// ─────────────────────────────────────────────────────────
let animFrame = null, animProgress = 0, animRunning = false;

function f_real(n) { return 3*n*n + 5*n; }
function f_ceil(n) { return 8*n*n; }

function drawBigOCanvas(progress) {
  const canvas = document.getElementById('bigOCanvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const W = canvas.offsetWidth, H = canvas.offsetHeight;
  canvas.width = W * dpr; canvas.height = H * dpr;
  ctx.scale(dpr, dpr);

  const PAD_L = 50, PAD_R = 20, PAD_T = 20, PAD_B = 36;
  const gW = W - PAD_L - PAD_R, gH = H - PAD_T - PAD_B;

  const N_MAX = 20;  // show n from 0 to 20
  const nCut = Math.floor(progress * N_MAX);
  const yMax = f_ceil(N_MAX) * 1.05;

  function xOf(n) { return PAD_L + (n / N_MAX) * gW; }
  function yOf(v) { return PAD_T + gH - (v / yMax) * gH; }

  // Background grid
  ctx.strokeStyle = 'rgba(255,255,255,.06)';
  ctx.lineWidth = 1;
  for (let i = 0; i <= 4; i++) {
    const y = PAD_T + (i / 4) * gH;
    ctx.beginPath(); ctx.moveTo(PAD_L, y); ctx.lineTo(W - PAD_R, y); ctx.stroke();
    const v = Math.round(yMax * (4-i) / 4);
    ctx.fillStyle = 'rgba(255,255,255,.35)';
    ctx.font = `${9*dpr/dpr}px DM Mono, monospace`;
    ctx.textAlign = 'right';
    ctx.fillText(v > 1000 ? (v/1000).toFixed(1)+'K' : v, PAD_L - 5, y + 3);
  }
  for (let n = 0; n <= N_MAX; n += 5) {
    const x = xOf(n);
    ctx.beginPath(); ctx.moveTo(x, PAD_T); ctx.lineTo(x, PAD_T + gH); ctx.stroke();
    ctx.fillStyle = 'rgba(255,255,255,.4)';
    ctx.textAlign = 'center';
    ctx.font = `${9*dpr/dpr}px DM Mono, monospace`;
    ctx.fillText('n='+n, x, PAD_T + gH + 16);
  }

  // Axis labels
  ctx.fillStyle = 'rgba(255,255,255,.5)';
  ctx.font = `${9*dpr/dpr}px DM Sans, sans-serif`;
  ctx.textAlign = 'center';
  ctx.fillText('operações', PAD_L - 38, PAD_T + gH/2);
  ctx.fillText('n (tamanho da entrada)', PAD_L + gW/2, H - 4);

  // Draw f_ceil (teto) as dashed orange
  ctx.strokeStyle = '#ff8a65';
  ctx.lineWidth = 2;
  ctx.setLineDash([5, 4]);
  ctx.beginPath();
  for (let n = 0; n <= nCut; n++) {
    const x = xOf(n), y = yOf(f_ceil(n));
    n === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
  }
  ctx.stroke();
  ctx.setLineDash([]);

  // Draw f_real (blue solid)
  ctx.strokeStyle = '#64b5f6';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  for (let n = 0; n <= nCut; n++) {
    const x = xOf(n), y = yOf(f_real(n));
    n === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
  }
  ctx.stroke();

  // n₀ marker at n=1
  if (nCut >= 1) {
    const x0 = xOf(1);
    ctx.strokeStyle = '#81c784';
    ctx.lineWidth = 1.5;
    ctx.setLineDash([3, 3]);
    ctx.beginPath(); ctx.moveTo(x0, PAD_T); ctx.lineTo(x0, PAD_T + gH); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#81c784';
    ctx.font = `bold ${10*dpr/dpr}px DM Sans, sans-serif`;
    ctx.textAlign = 'left';
    ctx.fillText('n₀=1', x0 + 4, PAD_T + 14);
  }

  // Labels at end of curves
  if (nCut >= N_MAX - 1) {
    const xe = xOf(N_MAX - 1);
    ctx.font = `${9*dpr/dpr}px DM Mono, monospace`;
    ctx.fillStyle = '#ff8a65';
    ctx.textAlign = 'left';
    ctx.fillText('8n²', xe - 28, yOf(f_ceil(N_MAX-1)) - 6);
    ctx.fillStyle = '#64b5f6';
    ctx.fillText('3n²+5n', xe - 60, yOf(f_real(N_MAX-1)) + 14);
  }
}

function animStep() {
  animProgress = Math.min(1, animProgress + 0.008);
  drawBigOCanvas(animProgress);
  if (animProgress < 1 && animRunning) {
    animFrame = requestAnimationFrame(animStep);
  } else {
    animRunning = false;
    const btn = document.getElementById('animPlayBtn');
    if (btn) { btn.textContent = '▶ Animar'; btn.classList.remove('active'); }
  }
}

function toggleAnim() {
  const btn = document.getElementById('animPlayBtn');
  if (animRunning) {
    animRunning = false;
    if (animFrame) cancelAnimationFrame(animFrame);
    btn.textContent = '▶ Animar'; btn.classList.remove('active');
  } else {
    animRunning = true;
    btn.textContent = '⏸ Pausar'; btn.classList.add('active');
    animFrame = requestAnimationFrame(animStep);
  }
}

function resetAnim() {
  animRunning = false;
  if (animFrame) cancelAnimationFrame(animFrame);
  animProgress = 0;
  drawBigOCanvas(0);
  const btn = document.getElementById('animPlayBtn');
  if (btn) { btn.textContent = '▶ Animar'; btn.classList.remove('active'); }
}

// ─────────────────────────────────────────────────────────
// N SLIDER — interactive counts
// ─────────────────────────────────────────────────────────
const N_STEPS = [10, 100, 1000, 10000, 100000];
const COMPLEXITIES = [
  { label:'O(1)', color:'#c8f0d8', bg:'#0a2d1a', fn: n => 1 },
  { label:'O(log n)', color:'#bfd8ff', bg:'#0a1a36', fn: n => Math.round(Math.log2(n)*10)/10 },
  { label:'O(n)', color:'#d4c4ff', bg:'#1a0a36', fn: n => n },
  { label:'O(n log n)', color:'#ffe0b0', bg:'#301a00', fn: n => Math.round(n*Math.log2(n)) },
  { label:'O(n²)', color:'#ffcccc', bg:'#2d0a0a', fn: n => n*n },
  { label:'O(n³)', color:'#ffaaa8', bg:'#3d0505', fn: n => n*n*n },
  { label:'O(2ⁿ)', color:'#ff8a80', bg:'#4a0000', fn: n => n <= 60 ? Math.pow(2,n) : Infinity },
];

function fmtNum(v) {
  if (!isFinite(v) || v > 1e15) return '> 10¹⁵ 🔥';
  if (v >= 1e12) return (v/1e12).toFixed(1) + ' trilhões';
  if (v >= 1e9) return (v/1e9).toFixed(1) + ' bilhões';
  if (v >= 1e6) return (v/1e6).toFixed(1) + ' milhões';
  if (v >= 1e3) return (v/1e3).toFixed(1) + ' mil';
  return v.toString();
}

function updateCounts(step) {
  const n = N_STEPS[parseInt(step)-1] || 100;
  document.getElementById('nDisplay').textContent = 'n = ' + n.toLocaleString('pt-BR');
  const grid = document.getElementById('countsGrid');
  if (!grid) return;
  grid.innerHTML = COMPLEXITIES.map(c => {
    const val = c.fn(n);
    const infeasible = !isFinite(val) || val > 1e15;
    return `<div class="count-card" style="background:${c.bg};border:1px solid rgba(255,255,255,.1)">
      <div class="count-label" style="color:${c.color}">${c.label}</div>
      <div class="count-val" style="color:${infeasible?'#ff6b6b':'white'}">${fmtNum(val)}</div>
    </div>`;
  }).join('');
}

// ─────────────────────────────────────────────────────────
// CODE ANNOTATOR
// ─────────────────────────────────────────────────────────
function toggleLine(idx) {
  const ex = document.getElementById('cl'+idx);
  const ann = document.getElementById('codeAnn');
  if (!ex || !ann) return;
  const allLines = ann.querySelectorAll('.code-line');
  const line = allLines[idx];
  const showing = ex.classList.contains('show');
  ann.querySelectorAll('.cl-explain').forEach(e => e.classList.remove('show'));
  ann.querySelectorAll('.code-line').forEach(l => l.classList.remove('active'));
  if (!showing) { ex.classList.add('show'); if (line) line.classList.add('active'); }
}


// ─────────────────────────────────────────────────────────
// DETAILS TOGGLE
// ─────────────────────────────────────────────────────────
function toggleDetails(trigger) {
  const content = trigger.parentElement.querySelector('.dt-content');
  const isOpen = content.classList.toggle('show');
  trigger.classList.toggle('open', isOpen);
  trigger.querySelector('.dt-arrow').textContent = isOpen ? '▾' : '▸';
}

const sidebar=document.getElementById('sidebar'),progressLine=document.getElementById('progressLine'),overlay=document.getElementById('sbOverlay');
const isMobile=()=>window.innerWidth<768;
const saved=localStorage.getItem('sb-state');
if(saved==='collapsed'&&!isMobile()){sidebar.classList.add('collapsed');progressLine.classList.add('visible')}
function toggleSidebar(){if(isMobile()){const o=sidebar.classList.toggle('open');overlay.classList.toggle('visible',o);return}const c=sidebar.classList.toggle('collapsed');progressLine.classList.toggle('visible',c);localStorage.setItem('sb-state',c?'collapsed':'expanded')}
const la=document.getElementById('lessonArea');
document.querySelectorAll('.section-nav a').forEach(a=>{
  a.addEventListener('click',e=>{e.preventDefault();const el=document.getElementById(a.getAttribute('href').slice(1));if(el)la.scrollTo({top:el.offsetTop-48,behavior:'smooth'})});
});
const secIds=[...document.querySelectorAll('section[id]')].map(s=>s.id);
// Init slider
updateCounts(2);
// Init canvas
const resizeCanvas = () => { drawBigOCanvas(animProgress); };
window.addEventListener('resize', resizeCanvas);
setTimeout(resizeCanvas, 100);

la.addEventListener('scroll',()=>{
  const st=la.scrollTop+60;let cur=secIds[0];
  secIds.forEach(id=>{const el=document.getElementById(id);if(el&&el.offsetTop<=st)cur=id});
  document.querySelectorAll('.section-nav a').forEach(a=>{a.classList.toggle('active',a.getAttribute('href')==='#'+cur)});
});

