      D: 'Há sim justificativa matemática: a definição formal de Big-O com o parâmetro c livre é exatamente o que torna as constantes absorvíveis. Não é apenas convenção.',
    }
  },
};

function answer(qid, el, chosen) {
  const box = document.getElementById(qid);
  if (box.dataset.answered) return;
  box.dataset.answered = '1';
  const correct = FEEDBACKS[qid].correct;
  const ok = chosen === correct;
  box.querySelectorAll('.quiz-option').forEach(o => {
    o.style.pointerEvents = 'none';
    const val = o.getAttribute('onclick').match(/'([A-E])'\)/);
    if (val && val[1] === correct) o.classList.add('correct');
  });
  if (!ok) el.classList.add('wrong');
  const fb = document.getElementById(qid + '-fb');
  let html = '';
  if (ok) {
    html = `<strong>✓ Correto!</strong> ${FEEDBACKS[qid].ok}`;
    fb.className = 'quiz-feedback show ok';
  } else {
    const whyWrong = FEEDBACKS[qid].why[chosen] || '';
    html = `<strong>✗ Incorreto.</strong><br><br>`
      + `<strong>Por que ${chosen} está errada:</strong> ${whyWrong}<br><br>`
      + `<strong>Por que ${correct} está certa:</strong> ${FEEDBACKS[qid].ok}`;
    fb.className = 'quiz-feedback show fail';
  }
  fb.innerHTML = html;
}
